const KEY='yantai-workspace-clean-v1';
try{if(!localStorage.getItem('yantai-cleared30')){for(const k of Object.keys(localStorage)){if(k==='yuncheng-demo-v1'||k.startsWith('yuncheng-draft-'))localStorage.removeItem(k)}localStorage.setItem('yantai-cleared30','1')}}catch{}
const stages=['需求调研','方案交流','报价商务','招投标','已签约','交付实施','运维服务','暂停'];
const seed={schemaVersion:3,modelVersion:3,projects:[],tasks:[],ledger:[],finance:[],audit:[]};
let data;try{data=JSON.parse(localStorage.getItem(KEY))||structuredClone(seed)}catch{data=structuredClone(seed)}
let page='工作台',selected=null,tab='概览',query='',filter='',view='table';
let projectScope=null;let projectFocus='all';
function projectFocusMatch(p){return projectFocus==='starred'?!!p.starred:projectFocus==='stale'?(new Date(today()+'T12:00:00')-new Date((latest(p)?.date||created(p))+'T12:00:00'))/86400000>=14:true}
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const id=()=>crypto.randomUUID();const today=()=>{let d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)};
function save(){localStorage.setItem(KEY,JSON.stringify(data))}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',2600)}
function badge(s){return `<span class="badge ${['运维服务','已签约'].includes(s)?'green':['报价商务','招投标'].includes(s)?'orange':''}">${esc(s)}</span>`}function getp(pid){return data.projects.find(p=>p.id===pid)}function latest(p){return recentRecords(p.events)[0]}function nav(s){projectScope=null;page=s;selected=null;query='';filter='';render()}function openp(pid){selected=pid;tab='概览';render()}
function stats(){const c=data.projects.filter(p=>p.confirmed&&p.basis.includes('/年')).reduce((s,p)=>s+(p.amount||0),0);return `<div class="stats"><div class="stat"><div class="stathead">项目总数 <span>▦</span></div><strong>${data.projects.length}<small>个</small></strong><div class="statnote">覆盖 ${new Set(data.projects.map(p=>p.unit)).size} 家客户单位</div></div><div class="stat"><div class="stathead">正在推进 <span>↗</span></div><strong>${data.projects.filter(p=>!['运维服务','暂停'].includes(p.stage)).length}<small>个</small></strong><div class="statnote"><span class="blue">从需求到交付</span> · 持续跟进</div></div><div class="stat"><div class="stathead">已确认合同年费 <span>¥</span></div><strong>${c.toLocaleString()}<small>万元/年</small></strong><div class="statnote">仅汇总已确认的年度合同金额</div></div><div class="stat"><div class="stathead">待办事项 <span>☷</span></div><strong>${data.tasks.filter(t=>!t.done).length}<small>项</small></strong><div class="statnote"><span class="orange">${data.tasks.filter(t=>!t.done&&t.date<=today()).length} 项已到期</span> · 及时处理</div></div></div>`}
function tasklist(all=false,pid=null){let ts=data.tasks.filter(t=>!pid||t.pid===pid);if(!all)ts=ts.filter(t=>!t.done);return ts.map(t=>`<div class="task"><input class="check" aria-label="完成：${esc(t.title)}" type="checkbox" ${t.done?'checked':''} data-task="${t.id}"><div class="tasktext" style="${t.done?'text-decoration:line-through;opacity:.5':''}">${esc(t.title)}<small>${esc(getp(t.pid)?.unit||'未关联')} · <span class="due">${esc(t.date)}</span></small></div></div>`).join('')||'<div class="empty">暂无待办</div>'}
function aside(){let es=data.projects.flatMap(p=>p.events.map(e=>({...e,p}))).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3);return `<aside class="aside"><div class="panel"><div class="panelhead"><h2>接下来要做</h2><button class="link" data-nav="待办与风险">全部 →</button></div>${tasklist()}</div><div class="panel"><div class="panelhead"><h2>最近动态</h2><span class="muted small">项目记录</span></div>${es.map(e=>`<div class="activity"><span class="blue">${esc(e.p.unit)}</span><br>${esc(e.title)}<br><small>${esc(e.date)} · ${esc(e.type)}</small></div>`).join('')}</div><div class="notice"><b>让每一次跟进都有迹可循</b><br>记录事实、保留来源。未确认的金额和结论，会在项目中清晰标注。</div></aside>`}
function projectlist(){let ps=data.projects.filter(p=>projectFocusMatch(p)&&(!projectScope||projectScope.includes(p.id))&&(!filter||p.stage===filter)&&[p.name,p.unit,p.bu,p.type,p.background,...p.events.map(e=>e.title+' '+e.body)].join(' ').toLowerCase().includes(query.toLowerCase()));return `<div class="panel"><div class="panelhead"><h2>项目总览 <span class="muted small" style="font-weight:400;margin-left:9px">${ps.length} 个项目</span></h2><div class="seg"><button data-view="table" class="${view==='table'?'on':''}">列表</button><button data-view="board" class="${view==='board'?'on':''}">看板</button></div></div><div class="filters"><input id="search" aria-label="搜索项目" placeholder="⌕  搜索项目、单位或进展…" value="${esc(query)}"><select id="filter" aria-label="项目阶段"><option value="">所有阶段</option>${stages.map(s=>`<option ${s===filter?'selected':''}>${s}</option>`).join('')}</select></div>${view==='table'?`<div class="tablewrap"><table><thead><tr><th>项目名称 / 客户单位</th><th>项目阶段</th><th>金额 / 口径</th><th>最近跟进</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr class="project" tabindex="0" data-project="${p.id}"><td><div class="pname">${esc(p.name)}</div><span class="muted">${esc(p.unit)}</span><span class="badge gray" style="margin-left:8px">${esc(p.bu)}</span></td><td>${badge(p.stage)}</td><td><div style="font-weight:600;margin-bottom:7px">${p.amount==null?'待确认':p.amount.toLocaleString()+' 万'}</div><span class="muted" style="font-size:10px">${esc(p.basis)}</span></td><td><div>${esc(latest(p)?.date||'暂无')}</div><div class="muted" style="font-size:10px;margin-top:7px;max-width:140px;overflow:hidden;text-overflow:ellipsis">${esc(latest(p)?.title||'暂无进展')}</div></td><td class="muted">↗</td></tr>`).join('')}</tbody></table></div>${!ps.length?'<div class="empty">没有匹配项目，试试其他关键词</div>':''}`:`<div class="board">${['前期沟通','商务采购','实施服务'].map((s,i)=>`<div class="boardcol"><h3>${s}</h3>${ps.filter(p=>i===0?['需求调研','方案交流'].includes(p.stage):i===1?['报价商务','招投标'].includes(p.stage):!['需求调研','方案交流','报价商务','招投标'].includes(p.stage)).map(p=>`<div class="boardcard" data-project="${p.id}" tabindex="0"><b>${esc(p.name)}</b><p>${esc(p.unit)}</p>${badge(p.stage)}</div>`).join('')}</div>`).join('')}</div>`}<div class="tablefoot"><span>金额按各自口径展示，不混合累计</span><span>共 ${ps.length} 条 · 点击查看项目 →</span></div></div>`}
function detail(){const p=getp(selected);let body='';if(tab==='概览')body=`<div class="pad"><h2>项目背景</h2><p style="color:#69788e;font-size:13px">${esc(p.background||'尚未补充项目背景')}</p><hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><dl class="kv"><dt>客户单位</dt><dd>${esc(p.unit)}</dd><dt>业务类型</dt><dd>${esc(p.type)}</dd><dt>所属行业</dt><dd>${esc(p.bu)}</dd><dt>项目负责人</dt><dd>${esc(p.owner)}</dd><dt>当前阶段</dt><dd>${badge(p.stage)}</dd><dt>项目金额</dt><dd>${p.amount==null?'待确认':esc(p.amount)+' 万元'} <span class="muted small">${esc(p.basis)}</span></dd></dl></div>`;
if(tab==='进展时间线')body=`<div class="pad"><div class="timeline">${recentRecords(p.events).map(e=>`<article class="event"><div class="eventtime">${esc(recordTimeLabel(e))}　${esc(e.type)}</div><h3 data-event-heading="${esc(e.id)}">${esc(e.title)}</h3><p>${esc(e.body)}</p></article>`).join('')||'<p class="muted">暂无进展，点击右上角记录第一条。</p>'}</div></div>`;
if(tab==='金额报价')body=`<div class="pad"><div class="heading"><h2>金额与报价版本</h2><button class="link" data-action="quote">＋ 添加金额</button></div><p class="muted small">预算、报价和合同分别记录；下表不直接求和。</p><div class="tablewrap"><table><thead><tr><th>版本 / 类型</th><th>费用名称</th><th>金额</th><th>口径</th><th>状态</th></tr></thead><tbody>${p.quotes.map(q=>`<tr><td>${esc(q.version)}</td><td>${esc(q.name)}</td><td>${esc(q.value)}</td><td>${esc(q.basis)}</td><td>${badge(q.status)}</td></tr>`).join('')}</tbody></table></div>${p.quotes.length?'':'<div class="empty">暂无报价记录，可添加一个金额版本</div>'}</div>`;
if(tab==='竞争分析')body=`<div class="pad"><div class="heading"><h2>竞争态势与应对</h2><button class="link" data-action="competitor">＋ 添加竞争方</button></div>${p.competitors.map(c=>`<div style="border:1px solid var(--line);border-radius:8px;padding:22px;margin:15px 0"><h2>${esc(c.name)} <span class="badge orange">${esc(c.status)}</span></h2><p class="muted small">${esc(c.product)} · 信息日期 ${esc(c.date)}</p><dl class="kv"><dt>对方优势</dt><dd>${esc(c.strength)}</dd><dt>待核实短板</dt><dd>${esc(c.weakness)}</dd><dt>我方应对</dt><dd>${esc(c.strategy)}</dd></dl><p class="muted small">来源：演示记录，需业务核实</p></div>`).join('')||'<div class="empty">暂无竞争记录；未知不代表没有竞争。</div>'}</div>`;
if(tab==='资料档案')body=`<div class="pad"><h2>项目资料</h2><p class="muted small">仅保存文件名称、大小等信息，不上传或读取文件正文。删除记录不会删除本机原文件。</p><input id="file" type="file" multiple aria-label="添加资料"><div style="margin-top:25px">${(p.files||[]).map((f,i)=>!f.deletedAt?`<div class="task"><span>▤</span><div class="tasktext">${esc(f.name)}<p class="muted small">${Math.ceil(f.size/1024)} KB · 原件仍在本机</p></div><button class="link" data-file-delete="${i}" aria-label="删除 ${esc(f.name)}">删除</button></div>`:'').join('')||'<div class="empty">暂无资料记录</div>'}</div>${(p.files||[]).some(f=>f.deletedAt)?`<details><summary>已删除的文件记录</summary>${p.files.map((f,i)=>f.deletedAt?`<div class="task"><div class="tasktext">${esc(f.name)}</div><button class="link" data-file-restore="${i}" aria-label="恢复 ${esc(f.name)}">恢复</button></div>`:'').join('')}</details>`:''}</div>`;
return `<div class="heading"><div><button class="link" data-action="back">← 返回项目台账</button><h1 style="margin-top:16px">${esc(p.name)}</h1><span class="muted small">${esc(p.unit)}　/　${esc(p.type)}　</span>${badge(p.stage)}</div><div class="actions"><button data-action="task">＋ 加待办</button><button class="primary" data-action="progress">＋ 记进展</button></div></div><div class="tabs">${['概览','进展时间线','金额报价','竞争分析','资料档案'].map(t=>`<button data-tab="${t}" class="${tab===t?'active':''}">${t}</button>`).join('')}</div><div class="detailgrid"><div class="panel">${body}</div><aside><div class="panel"><div class="panelhead"><h2>项目待办</h2><button class="link" data-action="task">＋</button></div>${tasklist(true,p.id)}</div></aside></div>`}
function other(){if(page==='待办与风险')return `<div class="panel"><div class="panelhead"><h2>全部待办</h2><button class="primary" data-action="task">＋ 新增待办</button></div>${tasklist(true)}</div>`;
if(page==='单位与联系人')return `<div class="panel"><div class="panelhead"><h2>客户单位</h2><span class="muted small">按项目关联汇总</span></div>${[...new Set(data.projects.map(p=>p.unit))].map(u=>`<div class="task"><span class="avatar">${esc(u[2]||u[0])}</span><div class="tasktext"><b>${esc(u)}</b><small>${data.projects.filter(p=>p.unit===u).length} 个关联项目 · 联系人待业务补充</small>${data.projects.filter(p=>p.unit===u).map(p=>`<button class="link" style="margin-top:12px" data-project="${p.id}">${esc(p.name)} →</button>`).join('')}</div></div>`).join('')}</div>`;
if(page==='资料知识库')return `<div class="panel"><div class="panelhead"><h2>资料索引</h2><span class="muted small">项目附件元数据</span></div><div class="pad"><p class="muted">在项目详情的「资料档案」中添加文件。演示版不读取本地知识库，也不上传文件正文。</p>${data.projects.flatMap(p=>(p.files||[]).filter(f=>!f.deletedAt).map(f=>`<div class="task"><div class="tasktext">${esc(f.name)}<small>${esc(p.name)} · ${Math.ceil(f.size/1024)} KB</small></div><button class="link" data-project="${p.id}">查看项目</button></div>`)).join('')||'<div class="empty">尚无资料记录</div>'}</div></div>`;
if(page==='统计导出')return `${stats()}<div class="panel pad"><h2>项目阶段分布</h2>${stages.map(s=>{let n=data.projects.filter(p=>p.stage===s).length;return `<div style="display:flex;gap:18px;align-items:center;margin:23px 0"><span style="width:80px;font-size:12px;color:#7b889b">${s}</span><div style="flex:1;background:#f1f4fa;height:9px;border-radius:5px"><div style="width:${n/data.projects.length*100||0}%;height:100%;background:#4777dd;border-radius:5px"></div></div><span>${n}</span></div>`}).join('')}<button data-action="export">导出完整演示数据（JSON）</button> <button data-action="csv">导出项目台账（CSV）</button></div>`;
return `<div class="panel pad"><h2>演示设置</h2><p class="muted">数据仅保存在当前浏览器的本地存储中。刷新后保留；清理浏览器数据可能丢失。</p><p class="muted small">这个版本不含服务器数据库、账号权限、AI提取或自动提醒推送。</p><button data-action="export">备份演示数据</button> <button data-action="reset">重置示例数据</button></div>`}
function render(){const ns=[['◫','数据总览'],['▦','项目台账'],['☷','待办'],['▤','资料库']];const old={'数据总览':'工作台','待办':'待办与风险','资料库':'资料知识库'};$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><span class="logo">◒</span><span class="word">云程<span class="brand-dot">.</span></span></div><div class="subbrand"></div><div class="navlabel">工作空间</div>${ns.map(([i,n])=>{let dest=old[n]||n;return `<button aria-label="${n}" class="nav ${page===dest?'active':''}" data-nav="${dest}"><span>${i}</span><span class="label">${n}</span>${n==='项目台账'?`<b>${data.projects.length}</b>`:''}</button>`}).join('')}<div class="sidebarfoot"><button class="nav" aria-label="设置与备份" data-nav="设置"><span>⚙</span><span class="label">设置与备份</span></button><div class="profile"><span class="avatar">我</span><div>个人工作空间<small>本地演示 · V0.2</small></div></div></div></aside><main class="main"><header class="top"><div class="crumb">我的工作空间 <span>/　${page==='工作台'?'数据总览':esc(page)}</span></div><div class="topright"><span class="demo">DEMO</span><span class="date">${today().replaceAll('-',' / ')}</span><button class="exit-screen" data-action="screen">退出大屏 ↙</button><span class="avatar">我</span></div></header><div class="content">${selected?detail():page==='工作台'?dashboard():`<div class="heading"><div><div class="eyebrow">PROJECT WORKSPACE</div><h1>${esc(page)}</h1><div class="muted small"></div></div><div class="actions"><button data-action="export">↓ 导出</button><button class="primary" data-action="new">＋ 新建项目</button></div></div>${page==='项目台账'?projectlist():other()}`}<div class="bottomnote"><span>云程 · 移动云项目工作台</span><span>示例项目以名称及来源标识</span></div></div></main></div>`;bind();bindDashboard()}
function bindDashboard(){document.querySelectorAll('[data-period]').forEach(el=>el.onclick=()=>{period=el.dataset.period;render()});document.querySelectorAll('[data-drill]').forEach(el=>el.onclick=()=>showDrill(el.dataset.drill));document.querySelectorAll('[data-phase]').forEach(el=>el.onclick=()=>{let s=el.dataset.phase,ids=periodData().ps.map(p=>p.id);nav('项目台账');projectScope=ids;filter=s;render()});document.querySelectorAll('[data-industry]').forEach(el=>el.onclick=()=>{let s=el.dataset.industry,ids=periodData().ps.map(p=>p.id);nav('项目台账');projectScope=ids;query=s;render()});for(const [selector,key] of [['#range-start','start'],['#range-end','end']])if($(selector))$(selector).onchange=e=>{let value=e.target.value;if(!value||value>today()||(key==='start'?value>customEnd:value<customStart)){toast('请选择有效的日期范围');render();return}if(key==='start')customStart=value;else customEnd=value;render()}}

function bind(){document.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>nav(el.dataset.nav));document.querySelectorAll('[data-project]').forEach(el=>{el.onclick=()=>openp(el.dataset.project);el.onkeydown=e=>{if(e.key==='Enter')openp(el.dataset.project)}});document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>{tab=el.dataset.tab;render()});document.querySelectorAll('[data-view]').forEach(el=>el.onclick=()=>{view=el.dataset.view;render()});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action));document.querySelectorAll('[data-task]').forEach(el=>el.onchange=()=>{data.tasks.find(t=>t.id===el.dataset.task).done=el.checked;save();render();toast('待办状态已保存')});if($('#search'))$('#search').oninput=e=>{let pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};if($('#filter'))$('#filter').onchange=e=>{filter=e.target.value;render()};if($('#file'))$('#file').onchange=e=>{let p=getp(selected);p.files=[...(p.files||[]),...Array.from(e.target.files).map(f=>({name:f.name,size:f.size}))];save();render();toast('文件信息已记录，未上传正文')}}
function field(label,name,type='text',value='',full=false){return `<label class="field ${full?'full':''}">${label}<input name="${name}" type="${type}" ${type==='number'?'step="any" min="0"':''} value="${esc(value)}" ${['name','unit','title'].includes(name)?'required':''}></label>`}function area(label,name){return `<label class="field full">${label}<textarea name="${name}"></textarea></label>`}function select(label,name,opts){return `<label class="field">${label}<select name="${name}">${opts.map(o=>Array.isArray(o)?`<option value="${esc(o[0])}">${esc(o[1])}</option>`:`<option>${esc(o)}</option>`).join('')}</select></label>`}
function modal(title,fields,submit){$('#modal').innerHTML=`<div class="overlay"><section class="dialog" role="dialog" aria-modal="true" aria-label="${title}"><div class="dialoghead"><h2>${title}</h2><button class="close" aria-label="关闭">×</button></div><form><div class="fields">${fields}</div><div class="formfoot"><button type="button" class="cancel">取消</button><button class="primary" type="submit">保存记录</button></div></form></section></div>`;let close=()=>$('#modal').innerHTML='';$('.close').onclick=close;$('.cancel').onclick=close;$('.overlay').onclick=e=>{if(e.target===$('.overlay'))close()};$('.dialog form').onsubmit=e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target));try{for(const k of ['name','unit','title'])if(k in v&&!v[k].trim())throw Error('必填项不能只包含空格');submit(v);save();close();render();toast('已保存到当前浏览器')}catch(err){toast('保存失败：'+err.message)}};$('.dialog input, .dialog select, .dialog textarea')?.focus()}
function download(content,type,name){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function action(a){if(a==='screen'){document.body.classList.toggle('screen-mode');return}if(a==='finance'){modal('记录签约 / 回款',select('关联项目','pid',data.projects.map(p=>[p.id,p.name]))+select('记录类型','kind',[['contract','合同签约'],['receipt','实际回款']])+field('发生日期','date','date',today())+field('金额（万元） *','value','number')+select('金额口径','basis',[['annual','年度合同金额（万元/年）'],['total','合同总额 / 实际到账（万元）']]),v=>{if(!v.value||Number(v.value)<=0)throw Error('请输入大于0的金额');if(v.kind==='receipt'&&v.basis!=='total')throw Error('回款请选择实际到账口径');data.finance??=[];data.finance.push({id:id(),pid:v.pid,kind:v.kind,date:v.date||today(),amount:Number(v.value),basis:v.basis})});return}if(a==='back'){selected=null;render()}if(a==='new')modal('登记一个新项目',field('客户单位 *','unit')+field('项目名称 *','name')+select('当前阶段','stage',stages)+select('所属行业','bu',['医卫','党政','金融','教育','企业','其他'])+field('业务类型','type')+field('金额（万元，可留空）','amount','number')+select('金额口径','basis',['预算线索 · 万元/年','项目估算 · 万元/总额','报价金额 · 万元/总额','合同金额 · 万元/年'])+field('记录日期','date','date',today())+area('项目背景','background'),v=>{if(v.amount!==''&&Number(v.amount)<0)throw Error('金额不能为负');let p={...v,id:id(),owner:'我',amount:v.amount===''?null:Number(v.amount),confirmed:false,createdDate:v.date||today(),events:[],competitors:[],quotes:[]};data.projects.unshift(p);selected=p.id;tab='概览'});
if(a==='progress')modal('记录项目新进展',field('发生时间','date','date',today())+select('进展类型','type',['客户沟通','需求调研','方案交流','报价商务','招投标','签约','交付实施','验收','回款','运维服务'])+field('进展标题 *','title','text','',true)+area('发生了什么 / 达成什么结论','body')+select('调整当前阶段','stage',['保持当前阶段',...stages])+field('下一步待办（可选）','task','text','',true)+field('待办截止日期','due','date',today()),v=>{let p=getp(selected);p.events.push({date:v.date||today(),title:v.title,type:v.type,body:v.body,source:v.source,recordedAt:new Date().toISOString()});if(v.stage!=='保持当前阶段')p.stage=v.stage;if(v.task.trim())data.tasks.push({id:id(),pid:p.id,title:v.task,date:v.due||today(),done:false});tab='进展时间线'});
if(a==='task')modal('添加下一步行动',select('关联项目','pid',(selected?[getp(selected)]:data.projects).map(p=>[p.id,p.name]))+field('截止日期','date','date',today())+field('待办事项 *','title','text','',true),v=>data.tasks.push({...v,id:id(),done:false}));
if(a==='quote')modal('添加金额记录',field('版本 / 金额类型','version')+field('费用名称 *','name')+field('金额 *','value','number')+select('口径','basis',['万元/年','万元/月','万元/总额','元/年','元/总额']),v=>{if(v.value===''||Number(v.value)<0)throw Error('请输入有效金额');getp(selected).quotes.push({...v,status:'已确认',value:Number(v.value)})});
if(a==='competitor')modal('添加竞争分析',field('竞争方名称 *','name')+field('产品 / 方案','product')+field('信息日期','date','date',today())+select('信息状态','status',['待核实','已确认（演示）'])+area('对方优势','strength')+area('待核实短板','weakness')+area('我方应对动作','strategy'),v=>getp(selected).competitors.push(v));
if(a==='export')download(JSON.stringify(data,null,2),'application/json','云程项目演示备份.json');if(a==='csv'){let csv=[['单位','项目名称','阶段','金额','金额口径','最新进展日期'],...data.projects.map(p=>[p.unit,p.name,p.stage,p.amount??'',p.basis,latest(p)?.date||''])].map(r=>r.map(c=>'"'+String(c).replaceAll('"','""')+'"').join(',')).join('\r\n');download('\ufeff'+csv,'text/csv;charset=utf-8','云程项目台账.csv')}
if(a==='reset')modal('恢复初始示例数据','<p class="muted">将清除当前浏览器新增的演示记录。请先导出备份，确认后点击保存记录。</p>',()=>{data=structuredClone(seed)})}
let period='week',customStart=today().slice(0,7)+'-01',customEnd=today(),drill=null;
// Add clearly synthetic historical examples once; preserve existing user records.
if(!data.dashboardVersion){
 const historical={p1:{created:'2026-08-12',events:[['2026-08-12','需求调研','建立初步需求档案'],['2026-09-08','方案交流','讨论混合算力架构']]},p2:{created:'2026-03-06',events:[['2026-03-06','需求调研','启动院区资源调研'],['2026-07-16','签约','完成年度云服务签约'],['2026-09-14','交付实施','确认首批迁移范围']]},p3:{created:'2026-01-15',events:[['2026-01-15','需求调研','建立资源池项目'],['2026-02-10','签约','年度资源池合同确认'],['2026-06-18','运维服务','完成资源容量回顾']]},p4:{created:'2026-09-18',events:[['2026-09-18','需求调研','梳理知识助手场景'],['2026-10-09','方案交流','完成首轮方案讨论']]},p5:{created:'2026-10-06',events:[['2026-10-06','需求调研','确认基层承载需求'],['2026-10-16','报价商务','准备报价与采购参数']]},p6:{created:'2026-10-20',events:[]}};
 for(const p of data.projects){const h=historical[p.id];if(h&&p.unit.startsWith('示例')){p.createdDate=h.created;p.events.push(...h.events.map(([date,type,title])=>({date,type,title,body:'用于展示周期变化的模拟历史记录。',source:'模拟历史数据'})));}}
 data.finance=[{id:'f1',pid:'p2',kind:'contract',date:'2026-07-16',amount:130,basis:'annual'},{id:'f2',pid:'p3',kind:'contract',date:'2026-02-10',amount:200,basis:'annual'},{id:'f3',pid:'p2',kind:'receipt',date:'2026-10-23',amount:32.5,basis:'total'},{id:'f4',pid:'p3',kind:'receipt',date:'2026-09-21',amount:50,basis:'total'},{id:'f5',pid:'p3',kind:'receipt',date:'2026-05-11',amount:50,basis:'total'}];data.dashboardVersion=2;save();
}
function range(){const end=today(),d=new Date(end+'T12:00:00');let start=end;if(period==='week'){d.setDate(d.getDate()-((d.getDay()+6)%7));start=localDate(d)}if(period==='month')start=end.slice(0,7)+'-01';if(period==='year')start=end.slice(0,4)+'-01-01';if(period==='custom')return {start:customStart,end:customEnd};return {start,end}}
function localDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
const created=p=>p.createdDate||p.date;const inRange=(date,r)=>date>=r.start&&date<=r.end;
function periodData(){const r=range(),ps=data.projects.filter(p=>created(p)<=r.end),ev=ps.flatMap(p=>p.events.filter(e=>inRange(e.date,r)).map(e=>({...e,p}))),fresh=ps.filter(p=>inRange(created(p),r)),progress=ps.filter(p=>ev.some(e=>e.p.id===p.id)),fin=(data.finance||[]).filter(f=>inRange(f.date,r)),signed=ps.filter(p=>fin.some(f=>f.pid===p.id&&f.kind==='contract'));return {r,ps,ev,fresh,progress,fin,signed}}
function money(n){return n.toLocaleString('zh-CN',{maximumFractionDigits:2})}
function bucketData(d){const a=new Date(d.r.start+'T12:00:00'),end=new Date(d.r.end+'T12:00:00'),days=Math.round((end-a)/86400000)+1,monthly=days>65,buckets=[];if(monthly){a.setDate(1);while(a<=end){let start=localDate(a);let b=new Date(a);b.setMonth(b.getMonth()+1);b.setDate(0);buckets.push({start:start<d.r.start?d.r.start:start,end:localDate(b)>d.r.end?d.r.end:localDate(b),label:(a.getMonth()+1)+'月'});a.setMonth(a.getMonth()+1)}}else{let step=days>14?7:1;while(a<=end){const start=localDate(a),b=new Date(a);b.setDate(b.getDate()+step-1);buckets.push({start,end:localDate(b)>d.r.end?d.r.end:localDate(b),label:step===1?start.slice(5).replace('-','/'):start.slice(5).replace('-','/')+'起'});a.setDate(a.getDate()+step)}}return buckets.map(b=>({...b,newCount:(d.all||d.ps).filter(p=>inRange(created(p),b)).length,progressCount:new Set(d.ev.filter(e=>inRange(e.date,b)).map(e=>e.p.id)).size,signCount:new Set(d.fin.filter(f=>f.kind==='contract'&&inRange(f.date,b)).map(f=>f.pid)).size}))}
function trendChart(d){const bs=bucketData(d),max=Math.max(2,...bs.flatMap(b=>[b.newCount,b.progressCount,b.signCount])),w=760,h=215,left=30,right=15,top=20,bottom=35,plotH=h-top-bottom,dx=(w-left-right)/Math.max(1,bs.length-1),x=i=>bs.length===1?w/2:left+i*dx,y=n=>top+plotH-n/max*plotH;const colors=['#007aff','#35b997','#b393e8'];return `<svg class="trend-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="期间项目新增、推进及签约趋势">${[0,1,2].map(i=>{let n=max*i/2;return `<line x1="${left}" y1="${y(n)}" x2="${w-right}" y2="${y(n)}" stroke="#edf0f3"/><text x="5" y="${y(n)+4}" fill="#9a9da5" font-size="10">${Number(n.toFixed(1))}</text>`}).join('')}${['newCount','progressCount','signCount'].map((key,j)=>`<polyline points="${bs.map((b,i)=>`${x(i)},${y(b[key])}`).join(' ')}" fill="none" stroke="${colors[j]}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${bs.map((b,i)=>`<circle cx="${x(i)}" cy="${y(b[key])}" r="3.4" fill="white" stroke="${colors[j]}" stroke-width="2"><title>${b.label} ${['新增','推进','签约'][j]} ${b[key]}个</title></circle>`).join('')}`).join('')}${bs.filter((b,i)=>bs.length<=12||i%2===0).map(b=>`<text x="${x(bs.indexOf(b))}" y="${h-8}" text-anchor="middle" fill="#969ba6" font-size="10">${b.label}</text>`).join('')}</svg>`}
function dashboard(){const d=periodData(),annual=d.fin.filter(f=>f.kind==='contract'&&f.basis==='annual').reduce((s,f)=>s+f.amount,0),total=d.fin.filter(f=>f.kind==='contract'&&f.basis==='total').reduce((s,f)=>s+f.amount,0),received=d.fin.filter(f=>f.kind==='receipt').reduce((s,f)=>s+f.amount,0),labels={week:'本周',month:'本月',year:'本年',custom:'所选期间'},label=labels[period],tiles=[['新增项目',d.fresh.length,'个','按登记日期','fresh'],['推进项目',d.progress.length,'个',d.ev.length+' 条进展记录','progress'],['签约项目',d.signed.length,'个','按合同发生日期','signed'],['新签合同年费',money(annual),'万元/年','合同总额另计 '+money(total)+' 万元','contract'],['实际回款',money(received),'万元','按到账日期累计','receipt']];
const phaseColors=['#007aff','#5a9cf5','#71bce3','#a995e1','#63bea4','#e9b96a','#98a4b9','#bec5cd','#c4c9d1'];let offset=0;const stageRows=stages.map((s,i)=>{let n=d.ps.filter(p=>p.stage===s).length;let part=d.ps.length?n/d.ps.length*100:0;let html=`<circle r="58" cx="78" cy="78" fill="none" stroke="${phaseColors[i]}" stroke-width="14" pathLength="100" stroke-dasharray="${part} ${100-part}" stroke-dashoffset="${-offset}" transform="rotate(-90 78 78)"/>`;offset+=part;return {s,n,html,i}});
return `<section class="dashboard"><div class="dash-title"><div><div class="eyebrow">YOUR PROJECTS, AT A GLANCE</div><h1>每一步进展，<span>清晰可见。</span></h1><p>聚焦重要的项目，让每一次推进都有方向。</p></div><div class="dash-actions"><button data-action="screen">⛶ 大屏模式</button><button class="primary" data-action="new">＋ 新建项目</button></div></div><div class="periodbar"><div><strong>${label}概览</strong><span class="range">${d.r.start.replaceAll('-','.')} — ${d.r.end.replaceAll('-','.')}</span></div><div class="period-control">${[['week','本周'],['month','本月'],['year','本年'],['custom','自定义']].map(([k,v])=>`<button data-period="${k}" aria-pressed="${period===k}" class="${period===k?'active':''}">${v}</button>`).join('')}</div></div>${period==='custom'?`<div class="customrange"><label>开始日期 <input id="range-start" type="date" value="${customStart}" max="${customEnd}"></label><label>结束日期 <input id="range-end" type="date" value="${customEnd}" min="${customStart}" max="${today()}"></label><span>按所选起止日期统计，含首尾两日</span></div>`:''}<div class="metric-grid">${tiles.map(([name,value,unit,note,key],i)=>`<button class="metric" data-drill="${key}" aria-label="查看${name}明细"><div class="metric-label">${name}<span>${['＋','↗','✓','¥','↓'][i]}</span></div><div class="metric-value">${value}<small>${unit}</small></div><div class="metric-note">${note}<span>↗</span></div></button>`).join('')}</div><div class="dash-main"><section class="panel trend-panel"><div class="panelhead"><div><h2>项目推进趋势</h2><p class="caption">${label}内的新增、推进与签约项目</p></div><div class="legend"><span style="--c:#007aff">新增</span><span style="--c:#35b997">推进</span><span style="--c:#b393e8">签约</span></div></div>${trendChart(d)}<div class="chart-foot">同一项目在每个时间段内去重计数 · 悬停数据点查看详情</div></section><section class="panel phase-panel"><div class="panelhead"><div><h2>项目阶段</h2><p class="caption">截至 ${d.r.end} 已登记项目 · 当前状态</p></div></div><div class="phase-body"><div class="ring"><svg viewBox="0 0 156 156" aria-label="项目阶段分布">${stageRows.map(s=>s.html).join('')}</svg><div><b>${d.ps.length}</b><span>项目总数</span></div></div><div class="phase-legend">${stageRows.filter(s=>s.n).map(s=>`<button data-phase="${s.s}"><i style="background:${phaseColors[s.i]}"></i>${s.s}<b>${s.n}</b></button>`).join('')||'<span class="muted">暂无项目</span>'}</div></div></section></div><div class="dash-bottom"><section class="panel"><div class="panelhead"><div><h2>重点进展</h2><p class="caption">${label}发生的最新项目动态</p></div><button class="link" data-nav="项目台账">查看项目 →</button></div><div class="focus-events">${[...d.ev].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4).map(e=>`<button class="focus-event" data-project="${e.p.id}"><span class="event-icon">${e.p.bu==='医卫'?'＋':'▦'}</span><span class="focus-copy"><b>${esc(e.title)}</b><span>${esc(e.p.unit)} · ${esc(e.type)}</span></span><time>${e.date.slice(5).replace('-','/')}</time><span class="chevron">›</span></button>`).join('')||'<div class="empty">这个期间还没有进展，记录第一步。</div>'}</div></section><section class="panel attention-panel"><div class="panelhead"><div><h2>值得关注</h2><p class="caption">当前未完成事项 · 不受时间筛选限制</p></div><button class="link" data-nav="待办与风险">全部 →</button></div>${tasklist()}<div class="attention-info"><span>待确认金额</span><b>${d.ps.filter(p=>!p.confirmed).length} 个项目</b></div></section><section class="panel industry-panel"><div class="panelhead"><div><h2>行业分布</h2><p class="caption">截至期末已登记的客户项目</p></div></div><div class="industries">${[...new Set(d.ps.map(p=>p.bu))].map((bu,i)=>{let n=d.ps.filter(p=>p.bu===bu).length;return `<button data-industry="${esc(bu)}"><div><span>${esc(bu)}</span><b>${n}<small> 个</small></b></div><div class="industry-track"><span style="width:${n/(d.ps.length||1)*100}%;background:${['#007aff','#7d9cc7','#9bb4ce'][i%3]}"></span></div></button>`}).join('')}<p class="caption">${new Set(d.ps.map(p=>p.unit)).size} 家客户单位 · 点击查看项目</p></div></section></div><div class="dash-footer"><span><i></i>数据已保存在本机浏览器</span><span>演示数据 · 金额按口径独立统计 <button class="link" data-action="finance">＋ 记签约 / 回款</button></span></div></section>`}
function showDrill(key){const d=periodData(),names={fresh:'新增项目',progress:'推进项目',signed:'签约项目',contract:'新签合同金额',receipt:'实际回款'};let content;if(['contract','receipt'].includes(key)){let fs=d.fin.filter(f=>key==='receipt'?f.kind==='receipt':f.kind==='contract');content=fs.map(f=>`<div class="drill-row"><div><b>${esc(getp(f.pid)?.name||'项目')}</b><p>${f.date} · ${f.basis==='annual'?'年度合同金额':'总额 / 到账金额'}</p></div><strong>${money(f.amount)} <small>${f.basis==='annual'?'万元/年':'万元'}</small></strong></div>`).join('')}else{const ps=key==='fresh'?d.fresh:key==='progress'?d.progress:d.signed;content=ps.map(p=>`<div class="drill-row"><div><b>${esc(p.name)}</b><p>${esc(p.unit)}</p></div>${badge(p.stage)}</div>`).join('')}modal(names[key]+'明细',`<div class="field full"><p class="muted">${d.r.start} — ${d.r.end}</p>${content||'<div class="empty">本期暂无记录</div>'}</div>`,()=>{});$('.dialog button[type="submit"]').textContent='完成'}

document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#modal').innerHTML=''});render();
